using System;using System.Collections.Generic;using System.Linq;using System.Net.Http;using System.Threading.Tasks;namespace WasiHttpClientFix{public class WasiCompatibleHttpClient:IDisposable{private readonly HttpClient _httpClient;public WasiCompatibleHttpClient(){_httpClient=new HttpClient(new WasiHttpMessageHandler());}public WasiCompatibleHttpClient(HttpMessageHandler handler){_httpClient=new HttpClient(new WasiHttpMessageHandler(handler));}public Task<HttpResponseMessage> GetAsync(string requestUri)=>_httpClient.GetAsync(requestUri);public Task<HttpResponseMessage> GetAsync(Uri requestUri)=>_httpClient.GetAsync(requestUri);public Task<HttpResponseMessage> PostAsync(string requestUri,HttpContent content)=>_httpClient.PostAsync(requestUri,content);public Task<HttpResponseMessage> SendAsync(HttpRequestMessage request)=>_httpClient.SendAsync(request);public void Dispose()=>_httpClient?.Dispose();}public class WasiHttpMessageHandler:DelegatingHandler{public WasiHttpMessageHandler():base(new HttpClientHandler()){}public WasiHttpMessageHandler(HttpMessageHandler innerHandler):base(innerHandler){}protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,System.Threading.CancellationToken cancellationToken){try{var response=await base.SendAsync(request,cancellationToken);FixResponseHeaders(response);return response;}catch(FormatException ex)when(IsContentLengthError(ex)){Console.WriteLine($"[WASI Fix] Caught Content-Length FormatException: {ex.Message}");throw new HttpRequestException("Invalid Content-Length header detected in WASI environment. The server returned Content-Length: -1 which is not supported.",ex);}}private static void FixResponseHeaders(HttpResponseMessage response){if(response.Headers.Contains("Content-Length")){var vals=response.Headers.GetValues("Content-Length").ToList();var invalid=vals.Any(v=>!IsValidContentLengthValue(v));if(invalid){Console.WriteLine("[WASI Fix] Removing invalid Content-Length header(s)");response.Headers.Remove("Content-Length");}}}private static bool IsValidContentLengthValue(string value){if(!long.TryParse(value,out var length)||length<0)return false;return true;}private static bool IsContentLengthError(FormatException ex){return ex.Message.Contains("Content-Length",StringComparison.OrdinalIgnoreCase)||ex.Message.Contains("header",StringComparison.OrdinalIgnoreCase);}}public static class WasiHeaderValidator{public static bool IsValidHeaderValue(string headerName,string value){if(string.IsNullOrEmpty(headerName)||string.IsNullOrEmpty(value))return false;if(string.Equals(headerName,"Content-Length",StringComparison.OrdinalIgnoreCase)){if(!long.TryParse(value,out var length)||length<0)return false;}return true;}public static IEnumerable<KeyValuePair<string,string>> FilterValidHeaders(IEnumerable<KeyValuePair<string,string>> headers){return headers.Where(kvp=>IsValidHeaderValue(kvp.Key,kvp.Value));}public static Dictionary<string,string> CleanHeaders(Dictionary<string,string> raw){var clean=new Dictionary<string,string>();foreach(var h in raw){if(IsValidHeaderValue(h.Key,h.Value))clean[h.Key]=h.Value;else Console.WriteLine($"[WASI Fix] Filtered invalid header: {h.Key}: {h.Value}");}return clean;}}}